  1	import { copyFile, mkdir, mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
  2	import { tmpdir } from 'node:os';
  3	import { basename, dirname, join } from 'node:path';
  4	import { pathToFileURL } from 'node:url';
  5	import type { HarnessDefaults, ModelCatalogEntry } from '@graphgoblin/contracts';
  6	import { FakeHarness } from '@graphgoblin/engine/testing';
  7	import {
  8	  DEFAULT_MODEL_CATALOG,
  9	  SqliteModelCatalog,
 10	  databaseView,
 11	  openDatabase,
 12	  openReadOnlyDatabaseClient,
 13	} from '@graphgoblin/infrastructure/sqlite';
 14	import { afterEach, beforeEach, describe, expect, it } from 'vitest';
 15	import { loadConfig } from './config.js';
 16	import { createContainer } from './container.js';
 17	import { runPreflightCli } from './preflight.js';
 18	
 19	const KEY = Buffer.alloc(32, 8).toString('base64');
 20	let dir: string;
 21	
 22	beforeEach(async () => {
 23	  dir = await mkdtemp(join(tmpdir(), 'gg-preflight-catalog-'));
 24	});
 25	
 26	afterEach(async () => {
 27	  globalThis.gc?.();
 28	  await rm(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 });
 29	});
 30	
 31	function adapters() {
 32	  return {
 33	    harnesses: { codex: new FakeHarness(), claude: new FakeHarness([], 'claude') },
 34	    deciders: [],
 35	    startTimers: false,
 36	  };
 37	}
 38	
 39	function env(dbFile: string, defaults: HarnessDefaults): Record<string, string> {
 40	  return {
 41	    GG_DATA_DIR: join(dir, 'data'),
 42	    GG_DB_URL: pathToFileURL(dbFile).href,
 43	    GG_MASTER_KEY: KEY,
 44	    GG_DEFAULTS: JSON.stringify(defaults),
 45	    GG_OLLAMA_ENABLED: 'false',
 46	  };
 47	}
 48	
 49	async function cli(environment: Record<string, string>) {
 50	  let out = '';
 51	  const code = await runPreflightCli({
 52	    env: environment,
 53	    ...adapters(),
 54	    write: (text) => {
 55	      out += text;
 56	    },
 57	  });
 58	  return { code, out };
 59	}
 60	
 61	async function fixture(dbFile: string, rows = DEFAULT_MODEL_CATALOG) {
 62	  await mkdir(dirname(dbFile), { recursive: true });
 63	  const handle = openDatabase({ url: pathToFileURL(dbFile).href });
 64	  try {
 65	    await handle.migrate();
 66	    await new SqliteModelCatalog(handle.db).seed(rows);
 67	    await handle.client.execute('PRAGMA wal_checkpoint(TRUNCATE)');
 68	  } finally {
 69	    handle.close();
 70	  }
 71	}
 72	
 73	/** SQLite readers update -shm read marks; only DB/WAL contain the stored data. */
 74	async function storeBytes(dbFile: string) {
 75	  const names = (await readdir(dirname(dbFile))).filter(
 76	    (name) => name === basename(dbFile) || name === `${basename(dbFile)}-wal`,
 77	  );
 78	  return Object.fromEntries(
 79	    await Promise.all(
 80	      names.map(async (name): Promise<[string, Buffer]> => [
 81	        name,
 82	        await readFile(join(dirname(dbFile), name)),
 83	      ]),
 84	    ),
 85	  );
 86	}
 87	
 88	function expectStoreUnchanged(
 89	  dbFile: string,
 90	  before: Record<string, Buffer>,
 91	  after: Record<string, Buffer>,
 92	) {
 93	  const dbName = basename(dbFile);
 94	  expect(after[dbName]?.equals(before[dbName]!)).toBe(true);
 95	  const walName = `${dbName}-wal`;
 96	  const existingWal = before[walName];
 97	  if (existingWal !== undefined) {
 98	    expect(after[walName]?.equals(existingWal)).toBe(true);
 99	  } else {
100	    // A reader may create an empty WAL, but cannot add frames to stored data.
101	    expect(after[walName]?.length ?? 0).toBe(0);
102	  }
103	}
104	
105	async function storedCatalog(dbFile: string) {
106	  const client = openReadOnlyDatabaseClient(dbFile);
107	  try {
108	    return await new SqliteModelCatalog(databaseView(client)).list();
109	  } finally {
110	    client.close();
111	  }
112	}
113	
114	async function storedMigrations(dbFile: string) {
115	  const client = openReadOnlyDatabaseClient(dbFile);
116	  try {
117	    return (await client.execute('SELECT * FROM __drizzle_migrations ORDER BY id')).rows;
118	  } finally {
119	    client.close();
120	  }
121	}
122	
123	describe('offline startup catalog admission', () => {
124	  it.each([
125	    ['codex', 'gpt-6.1-terra', 'medium'],
126	    ['claude', 'claude-opus-5-5', 'high'],
127	  ] as const)(
128	    'accepts a missing shipped %s seed without storing it',
129	    async (harness, model, effort) => {
130	      // The DB is outside GG_DATA_DIR and its URL is percent-encoded: both paths use startup's
131	      // projected catalog. This simulates a current-format store before its first upgrade start.
132	      const dbFile = join(dir, 'external store', 'gateway.db');
133	      await fixture(
134	        dbFile,
135	        DEFAULT_MODEL_CATALOG.filter(
136	          (entry) => !(entry.harness === harness && entry.model === model),
137	        ),
138	      );
139	      const defaults: HarnessDefaults = {
140	        byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' }, [harness]: { model, effort } },
141	      };
142	      const environment = env(dbFile, defaults);
143	      const before = await storeBytes(dbFile);
144	      const report = await cli(environment);
145	      expect(report.code, report.out).toBe(0);
146	      expect(report.out).toMatch(/ok\s+Database\s+reachable and migrated/);
147	      expect(report.out).toMatch(
148	        harness === 'codex'
149	          ? /ok\s+Default model\s+gpt-6.1-terra \(codex\) is in the model catalog/
150	          : /ok\s+Claude default model\s+Exact Claude model and effort are configured/,
151	      );
152	      expectStoreUnchanged(dbFile, before, await storeBytes(dbFile));
153	      expect(
154	        (await storedCatalog(dbFile)).some((row) => row.harness === harness && row.model === model),
155	      ).toBe(false);
156	      await expect(readdir(environment['GG_DATA_DIR']!)).rejects.toMatchObject({ code: 'ENOENT' });
157	
158	      const container = await createContainer(loadConfig(environment), adapters());
159	      try {
160	        await container.start();
161	        expect(await container.repos.catalog.findOne(harness, model)).toMatchObject({
162	          enabled: true,
163	        });
164	      } finally {
165	        await container.stop();
166	      }
167	    },
168	  );
169	
170	  it.each([
171	    {
172	      harness: 'codex',
173	      model: 'gpt-6.1-terra',
174	      effort: 'medium',
175	      enabled: false,
176	      status: 'WARN',
177	      code: 0,
178	      refusal: undefined,
179	    },
180	    {
181	      harness: 'claude',
182	      model: 'claude-opus-5-5',
183	      effort: 'high',
184	      enabled: false,
185	      status: 'FAIL',
186	      code: 1,
187	      refusal: undefined,
188	    },
189	    {
190	      harness: 'codex',
191	      model: 'unknown-model',
192	      effort: 'low',
193	      status: 'FAIL',
194	      code: 1,
195	      refusal: 'MODEL_NOT_IN_CATALOG',
196	    },
197	    {
198	      harness: 'codex',
199	      model: 'claude-opus-5-5',
200	      effort: 'high',
201	      status: 'FAIL',
202	      code: 1,
203	      refusal: 'MODEL_HARNESS_MISMATCH',
204	    },
205	    {
206	      harness: 'claude',
207	      model: 'gpt-6-luna',
208	      effort: 'low',
209	      status: 'FAIL',
210	      code: 1,
211	      refusal: 'MODEL_HARNESS_MISMATCH',
212	    },
213	    {
214	      harness: 'claude',
215	      model: 'claude-opus-5-5',
216	      effort: 'none',
217	      status: 'FAIL',
218	      code: 1,
219	      refusal: 'EFFORT_UNSUPPORTED',
220	    },
221	    {
222	      harness: 'claude',
223	      model: 'claude-opus-5-5',
224	      effort: 'low',
225	      efforts: ['high'],
226	      status: 'FAIL',
227	      code: 1,
228	      refusal: 'EFFORT_UNSUPPORTED',
229	    },
230	    // Codex preflight currently checks membership/enabled, while startup also checks effort.
231	    {
232	      harness: 'codex',
233	      model: 'gpt-5.5',
234	      effort: 'none',
235	      status: 'ok',
236	      code: 0,
237	      refusal: 'EFFORT_UNSUPPORTED',
238	    },
239	  ] as const)(
240	    'preserves $harness $model defaults (effort=$effort, status=$status)',
241	    async (test) => {
242	      const dbFile = join(dir, 'gateway.db');
243	      const rows: ModelCatalogEntry[] = DEFAULT_MODEL_CATALOG.map((entry) =>
244	        entry.harness === test.harness && entry.model === test.model
245	          ? {
246	              ...entry,
247	              ...('enabled' in test ? { enabled: test.enabled } : {}),
248	              ...('efforts' in test ? { efforts: [...test.efforts] } : {}),
249	            }
250	          : entry,
251	      );
252	      await fixture(dbFile, rows);
253	      const defaults: HarnessDefaults = {
254	        byHarness: {
255	          codex: { model: 'gpt-6-luna', effort: 'low' },
256	          [test.harness]: { model: test.model, effort: test.effort },
257	        },
258	      };
259	      const environment = env(dbFile, defaults);
260	      const before = await storeBytes(dbFile);
261	      const report = await cli(environment);
262	      expect(report.code, report.out).toBe(test.code);
263	      expect(report.out).toMatch(
264	        new RegExp(
265	          `${test.status}\\s+${test.harness === 'codex' ? 'Default model' : 'Claude default model'}\\s+`,
266	        ),
267	      );
268	      expect(await storedCatalog(dbFile)).toEqual(
269	        [...rows].sort(
270	          (a, b) => a.harness.localeCompare(b.harness) || a.model.localeCompare(b.model),
271	        ),
272	      );
273	      expectStoreUnchanged(dbFile, before, await storeBytes(dbFile));
274	      if (test.refusal) {
275	        const outcome: unknown = await createContainer(loadConfig(environment), adapters()).then(
276	          async (unexpected) => {
277	            await unexpected.stop();
278	            return undefined;
279	          },
280	          (error: unknown) => error,
281	        );
282	        expect(outcome).toMatchObject({
283	          code: 'EVALUATION_INVALID_CONFIGURATION',
284	          details: { code: test.refusal, harness: test.harness },
285	        });
286	        expectStoreUnchanged(dbFile, before, await storeBytes(dbFile));
287	      } else {
288	        // A disabled model is unavailable to execution, but is not malformed configuration:
289	        // ordinary boot must leave Settings available for correcting the selection.
290	        const container = await createContainer(loadConfig(environment), adapters());
291	        try {
292	          await container.start();
293	          expect(await container.repos.catalog.findOne(test.harness, test.model)).toMatchObject({
294	            enabled: false,
295	          });
296	          expect(
297	            await container.repos.catalog.isAllowed(test.harness, test.model, test.effort),
298	          ).toBe(false);
299	        } finally {
300	          await container.stop();
301	        }
302	      }
303	    },
304	  );
305	
306	  it.each(['absent', 'empty'] as const)(
307	    'preserves rows and migrations with an initially %s WAL',
